message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "손흥민이 차범근과 어깨를 나란히 한 58골 기록을 넘어설 수 있는 두 경기 중 하나라, 득점 동기가 최상이다.",
          "var_ids": ["R4"]
        },
        {
          "text": "남자 대표팀이 4연속 금메달을 따낸 전력이 있어 국제 무대에서 경기 주도권을 잡는 힘이 있다.",
          "var_ids": ["R2"]
        },
        {
          "text": "홈에서 열리는 경기라 홈 이점이 붙는다.",
          "var_ids": ["S03"]
        },
        {
          "text": "친선 경기라 실험 라인업이 가능하지만, 상대보다 두터운 자원으로 교체 카드를 활용할 수 있다.",
          "var_ids": ["S04"]
        }
      ],
      "breaks": [
        {
          "text": "김민재가 최근 경기 피로로 우즈베키스탄전에 나서기 어려워 중앙 수비가 약해진다.",
          "var_ids": ["R1"]
        },
        {
          "text": "직전 선발이었던 송범근·설영우·이한범이 오늘 명단에 없어 수비 조직이 재편된다.",
          "var_ids": ["IR02-home"]
        },
        {
          "text": "최근 5경기 L L W L D, 득점 평균 0.8(보정 0.25)로 득점 생산이 바닥에 가깝다.",
          "var_ids": ["S01-home"]
        },
        {
          "text": "친선 경기 특성상 실험 라인업과 잦은 교체로 조직력이 흐트러질 수 있다.",
          "var_ids": ["S04"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "최근 5경기 L L L W W, 득점 평균 1.8(보정 1.25)에 3경기 연속 득점으로 공격 흐름이 살아 있다.",
          "var_ids": ["S01-away"]
        },
        {
          "text": "상대 핵심 수비수 김민재가 피로로 결장할 가능성이 커 공격 부담이 줄어든다.",
          "var_ids": ["R1"]
        },
        {
          "text": "상대 직전 선발 3명이 명단에서 빠져 상대 수비 라인이 새로 짜인다.",
          "var_ids": ["IR02-home"]
        },
        {
          "text": "친선 경기라 상대가 실험 라인업을 돌리면 경기 흐름을 가져올 틈이 생긴다.",
          "var_ids": ["S04"]
        }
      ],
      "breaks": [
        {
          "text": "손흥민의 기록 도전 동기가 살아 있는 경기라 실점 위험이 커진다.",
          "var_ids": ["R4"]
        },
        {
          "text": "원정 경기라 상대의 홈 이점을 그대로 안고 시작한다.",
          "var_ids": ["S03"]
        },
        {
          "text": "상대는 국제 대회 4연속 금메달 전력이 있는 팀이라 경기 주도권을 내줄 수 있다.",
          "var_ids": ["R2"]
        },
        {
          "text": "최근 5경기에서 3연패가 섞여 있어 기복이 크다.",
          "var_ids": ["S01-away"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "대량득점형",
      "outcomes": [[3, 1], [4, 1]],
      "driver_vars": ["R4", "R2", "S03"],
      "mechanism": "홈팀이 홈 이점과 대회 전력으로 전반부터 상대 진영에 머물며, 손흥민의 기록 동기가 걸린 슈팅이 반복되어 다득점으로 이어진다. 상대는 한 골을 만회하지만 흐름을 되돌리지 못한다."
    },
    {
      "id": "우세팀_실점_동반형",
      "outcomes": [[2, 1], [3, 2]],
      "driver_vars": ["R4", "S01-away", "IR02-home"],
      "mechanism": "홈팀이 득점은 만들어내지만 직전 선발 3명이 빠진 수비 재편과 김민재 공백으로 실점을 허용한다. 상대의 3경기 연속 득점 흐름이 살아 있어 한두 골을 따라붙는다."
    },
    {
      "id": "핸디_대응형",
      "outcomes": [[1, 1], [0, 1]],
      "driver_vars": ["R1", "S04", "S01-home"],
      "mechanism": "홈팀의 중앙 수비 핵이 빠지고 친선 특성상 실험 라인업이 돌아가면서 최근 낮은 득점 흐름(평균 0.8)이 그대로 이어진다. 상대는 수비적으로 버티며 한 골 승부로 끌고 간다."
    },
    {
      "id": "회귀_반전형",
      "outcomes": [[0, 2], [1, 2]],
      "driver_vars": ["S01-home", "S01-away", "IR02-home"],
      "mechanism": "홈팀의 최근 5경기 0.8득점이라는 낮은 수치가 반등 없이 이어지고, 3연패 뒤 2연승으로 올라온 상대의 득점 흐름이 원정에서도 유지된다. 홈 수비 라인 재편이 그 흐름을 받쳐준다."
    },
    {
      "id": "친선_실험형",
      "outcomes": [[2, 0], [1, 0]],
      "driver_vars": ["S03", "S04", "R2"],
      "mechanism": "친선 경기라 양 팀 모두 교체를 많이 쓰지만, 홈 이점과 두터운 자원을 가진 홈팀이 후반 교체 싸움에서 우위를 점한다. 상대는 실험 라인업 운영 속에 득점을 만들지 못한다."
    }
  ]
}
